gayq(){return"B\u1ea5m K\u1ebft th\xfac phi\xean b\u1ea5t c\u1ee9 l\xfac n\xe0o, kh\xf4ng c\u1ea7n l\xfd do."},
gaym(){return"Gi\u1eef li\xean l\u1ea1c trong app"},
gayl(){return"Kh\xf4ng chia s\u1ebb s\u1ed1 \u0111i\u1ec7n tho\u1ea1i ho\u1eb7c giao d\u1ecbch ngo\xe0i app."},
gayp(){return"Quy t\u1eafc th\xed \u0111i\u1ec3m n\u1ed9i b\u1ed9 [ch\u1edd lu\u1eadt s\u01b0]."},
gaJE(){return"3. Quy t\u1eafc \u1ee9ng x\u1eed"},
gaJD(){return"T\xf4n tr\u1ecdng s\u1ef1 \u0111\u1ed3ng \xfd v\xe0 ranh gi\u1edbi c\u1ee7a nhau. Kh\xf4ng qu\u1ea5y r\u1ed1i, \u0111e d\u1ecda, c\u01b0\u1ee1ng \xe9p, mua b\xe1n d\u1ecbch v\u1ee5 t\xecnh d\u1ee5c ho\u1eb7c d\xf9ng app cho h\xe0nh vi tr\xe1i ph\xe1p lu\u1eadt. Kh\xf4ng \u0111\u0103ng n\u1ed9i dung g\u1ee3i d\u1ee5c ho\u1eb7c gi\u1ea3 m\u1ea1o danh t\xednh, tr\xecnh \u0111\u1ed9.\n\nCh\u1ec9 g\u1eb7p t\u1ea1i n\u01a1i ph\xf9 h\u1ee3p \u0111\u01b0\u1ee3c app cho ph\xe9p. H\u1ea1ng m\u1ee5c \u0111i nh\u1eadu b\u1eaft bu\u1ed9c \u1edf qu\xe1n \u0111\u1ed1i t\xe1c \u0111\xe3 duy\u1ec7t. Host kh\xf4ng c\xf3 ngh\u0129a v\u1ee5 u\u1ed1ng r\u01b0\u1ee3u bia; kh\xf4ng \xe9p u\u1ed1ng v\xe0 kh\xf4ng l\xe1i xe sau khi u\u1ed1ng. Kh\xf4ng qu\u1ea3ng c\xe1o nh\xe3n r\u01b0\u1ee3u bia, donate hay qu\xe0 t\u1eb7ng \u1ea3o trong app.\n\nGi\u1eef trao \u0111\u1ed5i trong app. Kh\xf4ng g\u1eedi s\u1ed1 \u0111i\u1ec7n tho\u1ea1i, \u0111\u01b0\u1eddng d\u1eabn li\xean l\u1ea1c ngo\xe0i app ho\u1eb7c \u0111\u1ecba ch\u1ec9 ri\xeang \u0111\u1ec3 n\xe9 c\xe1c bi\u1ec7n ph\xe1p b\u1ea3o v\u1ec7. Chat c\xf3 b\u1ed9 l\u1ecdc v\xe0 c\u1ea3nh b\xe1o sau khi b\u1ea1n \u0111\u1ed3ng \xfd x\u1eed l\xfd.\n\nB\xe1o c\xe1o h\u1ed3 s\u01a1, l\u01b0\u1ee3t \u0111\u1eb7t ho\u1eb7c tin nh\u1eafn khi c\u1ea7n. N\u1ebfu th\u1ea5y kh\xf4ng an to\xe0n, d\u1eebng phi\xean v\xe0 d\xf9ng thao t\xe1c b\xe1o s\u1ef1 c\u1ed1 ph\xf9 h\u1ee3p. SOS c\u1ee7a th\xed \u0111i\u1ec3m ch\u1ec9 t\u1ea1o c\u1ea3nh b\xe1o v\xe0 bi\xean nh\u1eadn m\xf4 ph\u1ecfng; kh\xf4ng b\u1ea3o \u0111\u1ea3m t\u1ed5ng \u0111\xe0i hay ng\u01b0\u1eddi th\xe2n th\u1eadt \u0111\xe3 nh\u1eadn, v\xe0 kh\xf4ng thay c\xe1ch li\xean h\u1ec7 c\u1ee9u tr\u1ee3 th\u1ef1c t\u1ebf.\n\nQu\u1ea3n tr\u1ecb xem x\xe9t th\xf4ng tin theo quy\u1ec1n v\xe0 ghi l\xfd do cho quy\u1ebft \u0111\u1ecbnh. B\xe1o c\xe1o \u0111\u01b0\u1ee3c ti\u1ebfp nh\u1eadn kh\xf4ng t\u1ef1 ch\u1ee9ng minh vi ph\u1ea1m. Quy tr\xecnh ch\u1ebf t\xe0i, khi\u1ebfu n\u1ea1i quy\u1ebft \u0111\u1ecbnh v\xe0 v\u1eadn h\xe0nh h\u1ed7 tr\u1ee3 ch\xednh th\u1ee9c v\u1eabn [ch\u1edd lu\u1eadt s\u01b0]."},
ga38(){return"X\xe1c nh\u1eadn c\xf3 m\u1eb7t"},
gavY(){return"Qu\xe9t m\xe3 QR c\u1ee7a qu\xe1n"},
gavF(){return"Qu\xe9t m\xe3 QR h\xf4m nay t\u1ea1i qu\xe1n. M\xe3 ch\u1ec9 d\xf9ng \u0111\u1ec3 x\xe1c nh\u1eadn c\xf3 m\u1eb7t; kh\xf4ng m\u1edf \u0111\u01b0\u1eddng d\u1eabn hay l\u01b0u \u1ea3nh."},
ga3m(){return"Check-in"},
gauw(){return"N\u01a1i g\u1eb7p n\xe0y kh\xf4ng ph\u1ea3i qu\xe1n \u0111\u1ed1i t\xe1c. C\u1ea3 hai x\xe1c nh\u1eadn c\xf3 m\u1eb7t \u0111\u1ec3 v\xe0o phi\xean."},
gauB(){return"V\xe0o phi\xean"},
gavG(){return"Check-in"},
gavE(){return"Qu\xe9t m\xe3 QR t\u1ea1i qu\u1ea7y c\u1ee7a qu\xe1n"},
gavD(){return"M\u1ed7i qu\xe1n \u0111\u1ed1i t\xe1c c\xf3 m\xe3 ri\xeang, \u0111\u1ed5i m\u1ed7i ng\xe0y. M\xe3 d\xf9ng \u0111\u1ec3 x\xe1c nh\u1eadn c\xf3 m\u1eb7t."},
ga3o(){return"L\u1ea5y m\u1ed9t m\u1eabu v\u1ecb tr\xed \u0111\u1ec3 ki\u1ec3m tra hai ng\u01b0\u1eddi \u1edf g\u1ea7n nhau. Ch\u1ec9 g\u1eedi khi b\u1ea1n x\xe1c nh\u1eadn; kh\xf4ng theo d\xf5i n\u1ec1n v\xe0 kh\xf4ng hi\u1ec3n th\u1ecb t\u1ecda \u0111\u1ed9 c\u1ee7a ng\u01b0\u1eddi kia."},
ga3n(){return"\u0110\u1ed3ng \xfd x\u1eed l\xfd v\u1ecb tr\xed cho check-in? B\u1ea1n c\xf3 th\u1ec3 r\xfat \u0111\u1ed3ng \xfd trong ph\u1ea7n quy\u1ec1n ri\xeang t\u01b0. Quy\u1ec1n v\u1ecb tr\xed c\u1ee7a thi\u1ebft b\u1ecb \u0111\u01b0\u1ee3c h\u1ecfi ri\xeang."},
gatz(){return"L\u1ea5y v\u1ecb tr\xed m\u1ed9t l\u1ea7n"},
gauG(){return"X\xe1c nh\u1eadn v\u1ecb tr\xed c\u1ee7a hai b\xean"},
auE(a){return"Hai m\xe1y c\u1ea7n c\xe1ch nhau t\u1ed1i \u0111a "+a+" m."},
