gauD(){return"B\u1ea1n c\u1ea7n x\xe1c nh\u1eadn v\u1ecb tr\xed"},
gauH(){return"\u0110\u1ed1i ph\u01b0\u01a1ng \u0111\xe3 x\xe1c nh\u1eadn"},
auA(a){return a+" \u0111\xe3 x\xe1c nh\u1eadn"},
gauF(){return"\u0110ang ch\u1edd x\xe1c nh\u1eadn chung"},
gaun(){return"\u0110\u1ed3ng \xfd d\xf9ng v\u1ecb tr\xed v\xe0 ti\u1ebfp t\u1ee5c"},
gav9(){return"M\u1edf c\xe0i \u0111\u1eb7t quy\u1ec1n thi\u1ebft b\u1ecb"},
gaub(){return"\u0110\xe3 \u0111\u1ecdc d\u1eef li\u1ec7u tr\xean thi\u1ebft b\u1ecb. Ch\u01b0a g\u1eedi x\xe1c nh\u1eadn c\xf3 m\u1eb7t."},
gatT(){return"T\xf4i \u0111ang c\xf3 m\u1eb7t t\u1ea1i n\u01a1i g\u1eb7p v\xe0 \u0111\u1ed3ng \xfd g\u1eedi d\u1eef li\u1ec7u n\xe0y \u0111\u1ec3 check-in."},
gaw2(){return"G\u1eedi x\xe1c nh\u1eadn c\xf3 m\u1eb7t"},
gawm(){return"M\xe1y ch\u1ee7 \u0111\xe3 nh\u1eadn x\xe1c nh\u1eadn c\u1ee7a b\u1ea1n. \u0110ang ch\u1edd \u0111\u1ed1i ph\u01b0\u01a1ng; phi\xean ch\u01b0a b\u1eaft \u0111\u1ea7u. B\u1ea5m c\u1eadp nh\u1eadt \u0111\u1ec3 xem k\u1ebft qu\u1ea3."},
ga37(){return"Hai x\xe1c nh\u1eadn ch\u01b0a kh\u1edbp ho\u1eb7c \u0111\xe3 h\u1ebft hi\u1ec7u l\u1ef1c. H\xe3y l\u1ea5y d\u1eef li\u1ec7u m\u1edbi v\xe0 x\xe1c nh\u1eadn l\u1ea1i."},
gavH(){return"C\u1eadp nh\u1eadt check-in"},
